/* @autogenerated */
import { Component, inject } from '@angular/core';
import { TenantLoginProvider } from 'app/features/identity/tenant-login-provider/model/tenant-login-provider.model';
import { TenantLoginProviderRepository } from 'app/features/identity/tenant-login-provider/repository/tenant-login-provider-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';

@Component({ selector: 'tenant-login-provider-view-enable-action', standalone: false, template: '' })
export class TenantLoginProviderViewEnableActionComponent extends ConfirmAction<TenantLoginProvider> {
  readonly name = 'enable';
  protected readonly scope = 'identity/tenant-login-provider';
  protected readonly repository = inject(TenantLoginProviderRepository);

  protected override appliesTo(items: TenantLoginProvider[]) {
    return items.every((item) => !item.enabled);
  }

  protected execute([item]: TenantLoginProvider[]) {
    return this.repository.enable(item.uid);
  }
}
